#[path = "solution.rs"]
mod solution;

use solution::{make_bell, BellError};

fn close(actual: f64, expected: f64) {
    let tolerance = 1e-14_f64.max(expected.abs() * 1e-12);
    assert!((actual - expected).abs() <= tolerance, "actual={actual}, expected={expected}");
}

#[test]
fn rejects_invalid_sigma_before_cutoff() {
    for sigma in [0.0, -1.0, f64::NAN, f64::INFINITY, f64::NEG_INFINITY] {
        assert!(matches!(make_bell(sigma, Some(-1.0)), Err(BellError::InvalidSigma)));
    }
}

#[test]
fn rejects_invalid_cutoff() {
    for cutoff in [-0.5, f64::NAN, f64::INFINITY, f64::NEG_INFINITY] {
        assert!(matches!(make_bell(1.0, Some(cutoff)), Err(BellError::InvalidCutoff)));
    }
}

#[test]
fn evaluates_normalized_symmetric_gaussian_without_cutoff() {
    let sigma = 2.0;
    let bell = make_bell(sigma, None).ok().unwrap();
    let normalization = 1.0 / (sigma * (2.0 * std::f64::consts::PI).sqrt());
    close(bell(0.0), normalization);
    close(bell(sigma), normalization * (-0.5_f64).exp());
    close(bell(-sigma), normalization * (-0.5_f64).exp());
    close(bell(3.0), bell(-3.0));
}

#[test]
fn cutoff_is_symmetric_strict_and_inclusive_at_boundaries() {
    let sigma = 2.0;
    let bell = make_bell(sigma, Some(1.5)).ok().unwrap();
    let boundary = 3.0;
    assert!(bell(boundary) > 0.0);
    close(bell(-boundary), bell(boundary));
    assert_eq!(bell(boundary + 0.001), 0.0);
    assert_eq!(bell(-boundary - 0.001), 0.0);

    let zero_cutoff = make_bell(1.0, Some(0.0)).ok().unwrap();
    assert!(zero_cutoff(0.0) > 0.0);
    assert_eq!(zero_cutoff(0.001), 0.0);
    assert_eq!(zero_cutoff(-0.001), 0.0);
}

#[test]
fn non_finite_evaluation_inputs_return_nan() {
    let bell = make_bell(1.0, Some(2.0)).ok().unwrap();
    assert!(bell(f64::NAN).is_nan());
    assert!(bell(f64::INFINITY).is_nan());
    assert!(bell(f64::NEG_INFINITY).is_nan());
}

